        button("Включить локальный TCP-фильтр",()->requireLocalAuth(()->{if(checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},NOTIFICATION_PERMISSION);return;}work(()->{CoreIdentity.get(this).issueNetworkGrant();post(this::prepareVpn);});}));
        button("Остановить Сеть",()->{NetworkVpnService.stopLocked(this);status.setText("Остановка локального фильтра запрошена. Tor-маршрутизация не использовалась.");});
