    private void prepareVpn(){if(!CoreIdentity.get(this).networkActive()){status.setText("Нужен действующий NETWORK_CONTROL");return;}Intent consent=android.net.VpnService.prepare(this);if(consent!=null)startActivityForResult(consent,VPN_PERMISSION);else startForegroundService(new Intent(this,NetworkVpnService.class));}
