    private void voiceServerDialog(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);EditText host=new EditText(this),port=new EditText(this),key=new EditText(this);host.setHint("Проверенный onion сервера Гласа");port.setHint("Порт");port.setText("80");key.setHint("Отдельный открытый ключ сервера Гласа");for(EditText field:List.of(host,port,key)){field.setSingleLine(true);field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(128)});form.addView(field);}new SecureDialogBuilder(this).setTitle("Сервер Гласа").setMessage("Проверьте onion и ключ по независимому доверенному источнику. Это отдельный ключ сервиса, он не заменяет ключ Identity.").setView(form).setNegativeButton("Отмена",null).setPositiveButton("Проверить",(d,w)->{String h=host.getText().toString().trim(),p=port.getText().toString().trim(),k=key.getText().toString().trim();work(()->{var config=new org.securemail.client.voice600.AndroidGlasSignalingClient600.Config(h,Integer.parseInt(p),IdentityProtocol.unb64(k,44));String hash=IdentityProtocol.id(config.servicePublic());post(()->new SecureDialogBuilder(this).setTitle("Подтвердите отпечаток сервиса").setMessage(hash).setNegativeButton("Отмена",null).setPositiveButton("Подтверждаю",(a,b)->work(()->{requireScope(IdentityProtocol.Scope.VOICE_CALL);stopVoice();com.google.gson.JsonObject j=new com.google.gson.JsonObject();j.addProperty("onion",config.onion());j.addProperty("port",config.port());j.addProperty("servicePublicKey",IdentityProtocol.b64(config.servicePublic()));vault.put("glas-server",j.toString().getBytes(StandardCharsets.UTF_8));})).show());});}).show();}
