    private boolean voiceForeground(long revision){return !activityClosed&&(activityResumed||microphonePermissions.pending()==MicrophonePermissionGate.Purpose.CALL)&&voiceRevision==revision&&localAuth>0&&SystemClock.elapsedRealtime()-localAuth<AndroidPolicy.LOCK_AFTER;}
