    private void startCodecTest(){requireScope(IdentityProtocol.Scope.VOICE_CALL);String selectedInput=inputDevice,selectedOutput=outputDevice;double volume=speakerVolume;long revision;synchronized(audioLock){if(recording)return;recording=true;revision=++audioRevision;}work(()->{GlasAudioSession owned=null;try{if(!recording||activityClosed||revision!=audioRevision)return;requireScope(IdentityProtocol.Scope.VOICE_CALL);owned=AndroidGlasAudio.localCodecTest(this,selectedInput,selectedOutput,volume,new GlasAudioSession.Listener(){public void level(double in,double out){post(()->{if(recording&&!activityClosed&&revision==audioRevision)status.setText("Локальная проверка Opus · микрофон "+(int)(in*100)+"% · выход "+(int)(out*100)+"%");});}public void failed(String reason){post(()->{if(!activityClosed&&revision==audioRevision)status.setText(reason);});}});synchronized(audioLock){if(!recording||activityClosed||revision!=audioRevision)return;requireScope(IdentityProtocol.Scope.VOICE_CALL);codecAudio=owned;owned.setMicrophoneEnabled(true);}long until=SystemClock.elapsedRealtime()+10_000;while(recording&&!activityClosed&&revision==audioRevision&&SystemClock.elapsedRealtime()<until){requireScope(IdentityProtocol.Scope.VOICE_CALL);Thread.sleep(100);}post(()->{if(!activityClosed&&revision==audioRevision)status.setText("Локальная проверка Opus завершена. Звук не сохранялся и не передавался в сеть");});}finally{if(owned!=null)owned.close();synchronized(audioLock){if(codecAudio==owned)codecAudio=null;if(revision==audioRevision)recording=false;}}});}
