    private void startMicrophoneTest(){long revision;synchronized(audioLock){if(recording)return;recording=true;revision=++audioRevision;}work(()->{AudioRecord r=null;short[] buffer=new short[1024];try{if(!recording||activityClosed||revision!=audioRevision)return;int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(min<=0||min>32768)throw new IOException("Аудиоформат недоступен");synchronized(audioLock){if(!recording||activityClosed||revision!=audioRevision)return;r=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(4096,min));if(r.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException("Микрофон не открылся");audio=r;r.startRecording();}long until=SystemClock.elapsedRealtime()+10_000,last=0;while(recording&&revision==audioRevision&&SystemClock.elapsedRealtime()<until){int n=r.read(buffer,0,buffer.length);if(n<0)throw new IOException("Микрофон отключён");long power=0;for(int i=0;i<n;i++)power+=(long)buffer[i]*buffer[i];int level=n==0?0:(int)Math.min(100,Math.sqrt(power/(double)n)*100/32768);Arrays.fill(buffer,(short)0);long now=SystemClock.elapsedRealtime();if(now-last>200){last=now;post(()->{if(!activityClosed&&revision==audioRevision)status.setText("Микрофон используется только для проверки · уровень "+level+"%");});}}post(()->{if(!activityClosed&&revision==audioRevision)status.setText("Проверка микрофона завершена. Звук не сохранялся");});}finally{Arrays.fill(buffer,(short)0);synchronized(audioLock){if(revision==audioRevision)recording=false;if(r!=null){try{r.stop();}catch(IllegalStateException ignored){}r.release();}if(audio==r)audio=null;}}});}
