    private void mailRelayConfig(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);EditText onion=new EditText(this);onion.setSingleLine(true);onion.setHint("Проверенный onion v3 Relay");form.addView(onion);EditText port=new EditText(this);port.setSingleLine(true);port.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);port.setHint("Порт Relay");form.addView(port);EditText key=new EditText(this);key.setHint("Отдельный проверенный ключ Relay, Base64URL");key.setSingleLine(true);form.addView(key);new SecureDialogBuilder(this).setTitle("Публичный адрес Relay").setMessage("Tor SOCKS берётся из подписанного приложения АЕГИС. Адрес Relay проверьте по доверенному источнику.").setView(form).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{String host=onion.getText().toString().trim(),number=port.getText().toString(),relayKey=key.getText().toString().trim();work(()->mailSession.configure(host,Integer.parseInt(number),relayKey));}).show();}
    private void requireScope(IdentityProtocol.Scope scope){if(broker==null||!broker.active()||!broker.capability().capabilities.contains(scope))throw new SecurityException("Для этого действия нужен действующий подписанный допуск приложения");}
    private void requireLocalAuth(Runnable action){if(localAuth>0&&SystemClock.elapsedRealtime()-localAuth<AndroidPolicy.LOCK_AFTER){action.run();return;}KeyguardManager kg=(KeyguardManager)getSystemService(KEYGUARD_SERVICE);if(!kg.isDeviceSecure()){message("Защита устройства","Сначала установите системный PIN, пароль или биометрию. Закрытые действия заблокированы.");startActivity(new Intent(Settings.ACTION_SECURITY_SETTINGS));return;}afterAuth=action;authCancellation=new CancellationSignal();new BiometricPrompt.Builder(this).setTitle("АЕГИС").setDescription("Подтвердите доступ к закрытым локальным данным").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL).build().authenticate(authCancellation,getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult result){Runnable next=afterAuth;afterAuth=null;authCancellation=null;if(next!=null&&!activityClosed){localAuth=SystemClock.elapsedRealtime();next.run();}}@Override public void onAuthenticationError(int code,CharSequence message){afterAuth=null;authCancellation=null;}});}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==VPN_PERMISSION&&result==RESULT_OK){prepareVpn();return;}if(result==RESULT_OK&&data!=null&&data.getData()!=null){if(request==SELECT_APK)inspect(data.getData());else if(request==SELECT_BACKUP){Uri uri=data.getData();requireLocalAuth(()->passwordDialog("Пароль защищённой копии",password->workSecret(password,()->{try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("Копия недоступна");mailSession.importBackup(input,password,mailAccount());post(()->status.setText("Identity и проверенные контакты восстановлены только в Почте; исходная копия сохранена"));}finally{Arrays.fill(password,'\0');}})));}}}
    private void requestMicrophone(MicrophonePermissionGate.Purpose purpose){if(activityClosed||purpose==MicrophonePermissionGate.Purpose.NONE)return;if(microphonePermissions.pending()!=MicrophonePermissionGate.Purpose.NONE){status.setText("Завершите текущий запрос микрофона");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED){runMicrophonePurpose(purpose);return;}int request;try{request=microphonePermissions.begin(purpose);}catch(IllegalStateException limit){status.setText(limit.getMessage());return;}requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},request);}
    private void runMicrophonePurpose(MicrophonePermissionGate.Purpose purpose){if(activityClosed||!activityResumed||localAuth<=0||SystemClock.elapsedRealtime()-localAuth>=AndroidPolicy.LOCK_AFTER)return;try{if(purpose==MicrophonePermissionGate.Purpose.CALL){requireScope(IdentityProtocol.Scope.VOICE_CALL);GlasRuntime r=voice;if(r!=null&&r.calls().snapshot().state()==org.securemail.client.voice.AndroidVoiceCallService.State.SECURE)r.calls().setMicrophoneEnabled(true);}else if(purpose==MicrophonePermissionGate.Purpose.CODEC_TEST){requireScope(IdentityProtocol.Scope.VOICE_CALL);startCodecTest();}else if(purpose==MicrophonePermissionGate.Purpose.MIC_TEST)startMicrophoneTest();}catch(RuntimeException unavailable){error(unavailable);}}
    private void cancelPendingMicrophone(){microphonePermissions.cancel();}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);boolean granted=results.length==1&&permissions.length==1&&Manifest.permission.RECORD_AUDIO.equals(permissions[0])&&results[0]==PackageManager.PERMISSION_GRANTED;MicrophonePermissionGate.Purpose purpose=microphonePermissions.consume(request,granted);if(purpose!=MicrophonePermissionGate.Purpose.NONE)runMicrophonePurpose(purpose);}
    @Override protected void onResume(){super.onResume();activityResumed=true;}
    @Override protected void onPause(){uiEpoch++;activityResumed=false;stopMicrophone();if(microphonePermissions.pending()!=MicrophonePermissionGate.Purpose.CALL)stopVoice();else{GlasRuntime r=voice;if(r!=null)r.calls().setMicrophoneEnabled(false);}super.onPause();}
    private long lastTouch;
    @Override public boolean dispatchTouchEvent(MotionEvent event){boolean handled=super.dispatchTouchEvent(event);long now=SystemClock.elapsedRealtime();if(AndroidPolicy.CORE.equals(getPackageName())&&event.getAction()==MotionEvent.ACTION_DOWN&&(event.getFlags()&(MotionEvent.FLAG_WINDOW_IS_OBSCURED|MotionEvent.FLAG_WINDOW_IS_PARTIALLY_OBSCURED))==0){try{if(SessionLedger.get(this).active())SessionLedger.get(this).touch();}catch(Exception ignored){}}if(broker!=null&&event.getAction()==MotionEvent.ACTION_DOWN&&(event.getFlags()&(MotionEvent.FLAG_WINDOW_IS_OBSCURED|MotionEvent.FLAG_WINDOW_IS_PARTIALLY_OBSCURED))==0&&now-lastTouch>5000){lastTouch=now;broker.touched();}return handled;}
    @Override protected void locked(){uiEpoch++;stopVoice();cancelPendingMicrophone();stopMicrophone();if(mailSession!=null)mailSession.close();for(AlertDialog d:new ArrayList<>(dialogs))if(d.isShowing())d.dismiss();dialogs.clear();localAuth=0;afterAuth=null;if(authCancellation!=null){authCancellation.cancel();authCancellation=null;}for(EditText field:privateFields)field.setText("");if(status!=null)status.setText("Закрытые действия заблокированы");}
    private void fullLogout(boolean finishAfter){locked();SessionLedger.get(this).lock();CoreBrokerService.revoked();if(!logoutPending.compareAndSet(false,true))return;workSecurity(()->{boolean remote=false;try{CoreIdentity.get(this).revokeRemote();remote=true;}catch(Exception offline){/* Local revoke remains mandatory when Tor or Identity is unavailable. */}finally{try{SessionLedger.get(this).logout();}finally{try{CoreBrokerService.exited();}finally{CoreIdentity.get(this).closeNetwork();logoutPending.set(false);}}}boolean confirmed=remote;postSecurity(()->{if(activityClosed)return;status.setText(confirmed?"Сервер подтвердил отзыв; локальная сессия завершена":"Локальная сессия завершена. Серверный отзыв не подтверждён");if(finishAfter)finish();});});}
    private void exit(){if(AndroidPolicy.CORE.equals(getPackageName())){fullLogout(true);return;}locked();finish();}
    @Override protected void onDestroy(){uiEpoch++;activityClosed=true;cancelPendingMicrophone();stopVoice();stopMicrophone();if(mailSession!=null)mailSession.close();if(isFinishing()&&AndroidPolicy.CORE.equals(getPackageName())){try{SessionLedger.get(this).logout();}catch(Exception ignored){/* remains locked in memory even if the disk is unavailable */}finally{CoreBrokerService.exited();}}if(broker!=null)broker.close();if(selected!=null)selected.delete();jobs.shutdownNow().forEach(UiWorkScheduler::discard);securityJobs.shutdown();super.onDestroy();}
    private interface Work {void run()throws Exception;}
    private void post(Runnable action){Long fromWorker=submittedEpoch.get();long expected=fromWorker==null?uiEpoch:fromWorker;ui.post(()->{if(!activityClosed&&uiEpoch==expected)action.run();});}
    private void postSecurity(Runnable action){ui.post(action);}
    private void work(Work task){schedule(jobs,false,task);}
    private void workSecurity(Work task){schedule(securityJobs,true,task);}
    private void workLetterSecrets(char[] password,char[] code,Work task){schedule(jobs,false,task,()->{Arrays.fill(password,'\0');Arrays.fill(code,'\0');});}
    private void workSecret(char[] secret,Work task){schedule(jobs,false,task,()->Arrays.fill(secret,'\0'));}
    private void schedule(java.util.concurrent.Executor executor,boolean security,Work task){schedule(executor,security,task,()->{});}
    private void schedule(java.util.concurrent.Executor executor,boolean security,Work task,Runnable discard){long expected=uiEpoch;try{UiWorkScheduler.execute(executor,security,expected,()->uiEpoch,()->activityClosed,()->{submittedEpoch.set(expected);try{task.run();}catch(Exception failure){if(security)postSecurity(()->error(failure));else post(()->error(failure));}finally{discard.run();submittedEpoch.remove();}},discard);}catch(RejectedExecutionException busy){discard.run();if(security){/* The dedicated lane accepts one idempotent logout; local denial remains synchronous. */logoutPending.set(false);try{SessionLedger.get(this).logout();}catch(Exception persistenceFailure){postSecurity(()->error(persistenceFailure));}finally{CoreBrokerService.exited();CoreIdentity.get(this).closeNetwork();}postSecurity(()->error(busy));}else message("Операция занята","Дождитесь завершения текущей проверки");}}
    private void error(Exception e){if(activityClosed)return;String message=e.getMessage();status.setText(message==null?"Операция недоступна":message.substring(0,Math.min(320,message.length())));}
    private void message(String title,String value){if(!activityClosed){AlertDialog d=new SecureDialogBuilder(this).setTitle(title).setMessage(value).setPositiveButton("Понятно",null).show();TextView content=d.findViewById(android.R.id.message);if(content!=null)content.setTextIsSelectable(true);}}
    private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+0.5f);}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setPadding(0,dp(5),0,dp(7));body.addView(t,new LinearLayout.LayoutParams(-1,-2));return t;}
    private void button(String value,Runnable clicked){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setMinHeight(dp(44));b.setFilterTouchesWhenObscured(true);b.setOnClickListener(v->clicked.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(4);p.bottomMargin=dp(4);body.addView(b,p);}
